function switchPlaybackBudget(events:readonly BattleVisualEvent[], enabled:boolean){return enabled?2800+6500*Math.min(4,events.filter(event=>event.kind==='switch').length)+1200*Math.min(6,events.filter(reviewedAttackKind).length)+6500*Math.min(4,events.filter(event=>event.kind==='form'&&event.pokemon?.mega===true).length)+1000*Math.min(4,events.filter(event=>event.kind==='form'&&event.transformation==='zpower').length)+1000*Math.min(4,events.filter(event=>event.kind==='move'&&event.moveId==='breakneckblitz').length)+300*Math.min(12,events.filter(event=>event.kind==='damage'&&event.hit).length):2800;}
function eventDuration(e:BattleVisualEvent){if(e.kind==='capture'||e.kind==='captureAttempt')return 650+Math.min(3,Number(e.shakes)||0)*250;if(battleEventHasBurst(e))return 780;return e.kind==='move'?440:e.kind==='damage'||e.kind==='heal'?360:e.kind==='switch'||e.kind==='faint'?420:e.kind==='status'?340:240;}
const classicBiomes=new Set('town plains grass tall_grass metropolis forest sea swamp beach lake seabed mountain badlands cave desert ice_cave meadow power_plant volcano graveyard dojo factory ruins wasteland abyss space construction_site jungle fairy_cave temple slum snowy_forest island laboratory end'.split(' '));
