function HP({p,inside=false}:{p:any;inside?:boolean}){const fraction=Math.max(0,Math.min(1,p.hp/Math.max(1,p.maxHp)));return <div className="bs-health"><div className="bs-hp-row"><b>HP</b>{!inside&&<span>{p.hp}<small> / {p.maxHp}</small></span>}</div><div className="bs-hp-track" role="progressbar" aria-label={`${p.name} HP`} aria-valuemin={0} aria-valuemax={p.maxHp} aria-valuenow={p.hp}><i className={fraction<=.25?'danger':fraction<=.5?'warning':''} style={{transform:`scaleX(${fraction})`}}/>{inside&&<span className="bs-hp-inside" aria-hidden="true">{p.hp} / {p.maxHp}</span>}{Number(p.rogueBossSegments)>1&&Array.from({length:p.rogueBossSegments-1},(_,i)=><span className="bs-boss-tick" key={i} style={{left:((i+1)/p.rogueBossSegments*100)+'%'}} aria-hidden="true"/>)}</div>{Number(p.rogueBossSegments)>1&&<small className="bs-boss-shields">보스 실드 · {p.rogueBossSegmentIndex??p.rogueBossSegments-1}개 남음</small>}</div>}
